```c
Py_hash_t
_Py_HashPointerRaw(const void *p)
{
    uintptr_t x = (uintptr_t)p;
    x = (x >> 4) | (x << (8 * sizeof(uintptr_t) - 4));
    return (Py_hash_t)x;
}
Py_hash_t
_Py_HashPointer(const void *p)
{
    Py_hash_t x = _Py_HashPointerRaw(p);
    if (x == -1) {
