        while True:
            if t[i] is None:
                t[i]=k; break
            perturb >>= 5
            i=(i*5+1+perturb)&mask
    return [x for x in t if x is not None]
def br_slots(hs, n=8, LINEAR=9):
    t=[None]*n
    for k,h in enumerate(hs):
        mask=n-1; perturb=h; i=h&mask; free=None
        while True:
            probes = LINEAR if i+LINEAR<=mask else 0
            inserted=False
            for j in range(probes+1):
                idx=i+j
                if t[idx] is None:
                    at = free if free is not None else idx
                    t[at]=k; inserted=True; break
            if inserted: break
            perturb >>= 5
